[CmdletBinding()]
param([Parameter(Mandatory)][string]$Root,[Parameter(Mandatory)][string]$BuildRoot,[ValidateSet('Title','Probe')][string]$Scenario='Title',[int]$Repetition=1,[double]$Seconds=60,[double]$Warmup=10)
$ErrorActionPreference='Stop';$Root=[IO.Path]::GetFullPath($Root);$BuildRoot=[IO.Path]::GetFullPath($BuildRoot);$runtime=Join-Path $Root 'Runtime'
if((Get-Content "$Root/owner.json" -Raw|ConvertFrom-Json).kind -ne 'PERF-02 isolated capability validation'){throw 'Owned PERF02 root required'}
$profile=Get-Content "$BuildRoot/perf02-profile.json" -Raw|ConvertFrom-Json;if($profile.profile -ne 'Perf02'){throw 'Owned capability build required'};$label=$profile.variant+'-'+$Scenario+'-R'+$Repetition+'-'+[guid]::NewGuid().ToString('N').Substring(0,6);$storage=Join-Path $runtime "Cases/$label";$sys=Join-Path $runtime "System/$label";New-Item -ItemType Directory $storage,$sys|Out-Null
@{variant=$profile.variant;scenario=$Scenario;repetition=$Repetition;seconds=$Seconds;warmup=$Warmup;build=$BuildRoot;utc=[datetime]::UtcNow.ToString('o');input='Missing synthetic progress; no scene selection, no Run created';scope='Independent private inactive desktop; not native/human'}|ConvertTo-Json|Set-Content "$storage/perf02-config.json"
if($profile.variant -eq 'C'){@{scenario='Title';repetition=$Repetition;seconds=$Seconds;warmup=$Warmup;sampling=$true}|ConvertTo-Json|Set-Content "$storage/perf-config.json"}
$side=$null;$stdout=$null;$stderr=$null;$pwsh=(Get-Process -Id $PID).Path;$exe=Join-Path $BuildRoot 'Results/Release/WanxiangGuitu.exe'
if($profile.variant -eq 'C'){$si=[Diagnostics.ProcessStartInfo]::new();$si.FileName=$pwsh;$si.UseShellExecute=$false;$si.WindowStyle='Hidden';$si.RedirectStandardOutput=$true;$si.RedirectStandardError=$true;foreach($v in @('-NoProfile','-File',"$PSScriptRoot/Perf02System.ps1",'-RuntimeRoot',$runtime,'-StorageRoot',$storage,'-ExpectedExe',$exe,'-OutputRoot',$sys)){$si.ArgumentList.Add($v)};$side=[Diagnostics.Process]::Start($si);$stdout=$side.StandardOutput.ReadToEndAsync();$stderr=$side.StandardError.ReadToEndAsync()}
$start=[datetime]::UtcNow;& "$PSScriptRoot/../DeliveryPlayer02/Invoke-P02Case.ps1" -ParentRoot $runtime -StorageRoot $storage -Mode Observe -BuildRoot $BuildRoot -WorkerPath "$runtime/Worker/NativeProbe.dll";$code=$LASTEXITCODE
$stopped=$true;$sideExit=$null;if($side){Set-Content "$storage/system-stop" 'Runtime finished, no kill';$stopped=$side.WaitForExit(30000);if($stopped){$sideExit=$side.ExitCode;$stdout.Result|Set-Content "$sys/stdout";$stderr.Result|Set-Content "$sys/stderr"}}
@{variant=$profile.variant;scenario=$Scenario;repetition=$Repetition;storage=$storage;build=$BuildRoot;start=$start.ToString('o');end=[datetime]::UtcNow.ToString('o');launcherExit=$code;sidecarStopped=$stopped;sidecarExit=$sideExit;scriptSha256=(Get-FileHash $PSCommandPath).Hash}|ConvertTo-Json|Set-Content "$storage/case-result.json"
Write-Output "CASE=$storage";if($code -ne 0 -or !$stopped -or ($side -and $sideExit -ne 0)){exit 1};exit 0
